def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue

            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            not seen[ny][nx] and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)

            # A near-filled bounding box indicates a rectangle with stray
            # cells of other colors replacing some of its interior.
            if area >= 4 and len(cells) / area >= 0.65:
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
                continue

            # Restore a rectangle whose visible part is a long, one-cell-wide
            # edge, with other non-background marks alongside it.
            if len(cells) >= 4 and (r0 == r1 or c0 == c1):
                if r0 == r1:
                    length = c1 - c0 + 1
                    for nr0, nr1 in ((r0 - 1, r1 - 1), (r0 + 1, r1 + 1)):
                        if 0 <= nr0 < h:
                            count = sum(grid[nr0][x] != bg for x in range(c0, c1 + 1))
                            if count >= max(2, length // 2):
                                for x in range(c0, c1 + 1):
                                    out[nr0][x] = color
                                for x in range(c0, c1 + 1):
                                    out[r0][x] = color
                else:
                    length = r1 - r0 + 1
                    for nc0, nc1 in ((c0 - 1, c1 - 1), (c0 + 1, c1 + 1)):
                        if 0 <= nc0 < w:
                            count = sum(grid[y][nc0] != bg for y in range(r0, r1 + 1))
                            if count >= max(2, length // 2):
                                for y in range(r0, r1 + 1):
                                    out[y][nc0] = color
                                for y in range(r0, r1 + 1):
                                    out[y][c0] = color

    return out
